// Fill spots freed by cancellations from the waitlist.
// Founding-tier members go first (waitlist order otherwise);
// anyone who has declined a spot twice or more is dropped from the waitlist.
export function promoteFromWaitlist(cls, cancelled) {
  const gone = new Set(cancelled);
  const booked = cls.booked.filter((name) => !gone.has(name));
  const eligible = cls.waitlist.filter((m) => m.declines < 2);
  const ordered = [
    ...eligible.filter((m) => m.tier === "founding"),
    ...eligible.filter((m) => m.tier !== "founding"),
  ];
  const free = Math.max(0, cls.capacity - booked.length);
  const promoted = ordered.slice(0, free);
  return {
    booked: [...booked, ...promoted.map((m) => m.name)],
    waitlist: ordered.slice(free),
  };
}
EOF
