const ML_PER_UNIT = { cup: 240, tbsp: 15, tsp: 5 };

// Converts a cup/tbsp/tsp amount to millilitres, rounded to the nearest 5 ml.
// Amounts under 3 teaspoons (15 ml) stay in teaspoons, unconverted.
export function toMetric(amount, unit) {
  if (!Object.hasOwn(ML_PER_UNIT, unit)) {
    throw new RangeError(`Unsupported unit: ${unit}`);
  }
  const ml = amount * ML_PER_UNIT[unit];
  if (ml < 15) return { amount: ml / ML_PER_UNIT.tsp, unit: "tsp" };
  return { amount: Math.round(ml / 5) * 5, unit: "ml" };
}
