import { overlaps } from './shifts.js';

// Minimum hours off between the end of one shift and the start of the next.
const MIN_REST = 11;

// Whether the worker can take the shift, given their other shifts.
// Times are hours from the start of the week.
export function canSwap(worker, shift, schedule) {
  if (worker.trainee && shift.night) return false;
  return schedule.every((other) => {
    if (overlaps(shift, other)) return false;
    const gap = shift.start >= other.end
      ? shift.start - other.end
      : other.start - shift.end;
    return gap >= MIN_REST;
  });
}
EOF
