import { points } from "./results.js";

// A forfeited match counts as a 0-3 loss, whatever score was entered.
function effective(r) {
  return r.forfeit ? { for: 0, against: 3 } : r;
}

// Team names, most points first; ties are broken by goal difference.
export function standings(teams) {
  const rows = teams.map(({ name, results }) => {
    const rs = results.map(effective);
    return {
      name,
      pts: rs.reduce((n, r) => n + points(r), 0),
      diff: rs.reduce((n, r) => n + r.for - r.against, 0),
    };
  });
  rows.sort((a, b) => b.pts - a.pts || b.diff - a.diff);
  return rows.map((r) => r.name);
}
EOF
