import { parseBin } from "./bins.js";

// Walking order: aisles from A, snaking (A, C, E... slot up; B, D, F... slot down).
function walkKey(bin) {
  const { aisle, slot, level } = parseBin(bin);
  const index = aisle.charCodeAt(0) - 65;
  return [index, index % 2 === 0 ? slot : -slot, level];
}

function byWalk(a, b) {
  const ka = walkKey(a.bin);
  const kb = walkKey(b.bin);
  return ka[0] - kb[0] || ka[1] - kb[1] || ka[2] - kb[2];
}

// SKUs in picking order; frozen items go last, walked the same way.
export function pickOrder(items) {
  const walk = (list) => [...list].sort(byWalk).map((item) => item.sku);
  return [...walk(items.filter((i) => !i.frozen)), ...walk(items.filter((i) => i.frozen))];
}
EOF
