// Hours-weighted tip pool. Amounts are in cents.
// Kitchen hours count half; leftover cents go to whoever worked the most hours.
export function poolByHours(totalCents, staff) {
  const weight = (s) => (s.role === "kitchen" ? s.hours / 2 : s.hours);
  const totalWeight = staff.reduce((sum, s) => sum + weight(s), 0);
  if (!(totalWeight > 0)) throw new RangeError("no hours to pay");
  const pay = staff.map((s) => Math.floor((totalCents * weight(s)) / totalWeight));
  const top = staff.reduce((best, s, i) => (s.hours > staff[best].hours ? i : best), 0);
  pay[top] += totalCents - pay.reduce((a, b) => a + b, 0);
  return Object.fromEntries(staff.map((s, i) => [s.name, pay[i]]));
}
EOF
