import { average } from "./grades.js";

// Letter grade for a student's scores: A from 90, B from 80, C from 70, else F.
// With four or more scores, the single lowest one is dropped before averaging.
export function letterGrade(scores) {
  let used = scores;
  if (scores.length >= 4) {
    const lowest = Math.min(...scores);
    used = [...scores];
    used.splice(used.indexOf(lowest), 1);
  }
  const avg = average(used);
  if (avg >= 90) return "A";
  if (avg >= 80) return "B";
  if (avg >= 70) return "C";
  return "F";
}
