// Internet is split evenly, electricity by floor area. Each share is floored and
// the leftover cents go to the account holder (first room if none is marked),
// so the totals are exact.
export function splitUtilities({ internetCents, electricityCents }, rooms) {
  const area = rooms.reduce((a, r) => a + r.m2, 0);
  const out = rooms.map((r) =>
    Math.floor(internetCents / rooms.length) + Math.floor((electricityCents * r.m2) / area));
  const leftover = internetCents + electricityCents - out.reduce((a, c) => a + c, 0);
  const holder = Math.max(0, rooms.findIndex((r) => r.accountHolder));
  out[holder] += leftover;
  return Object.fromEntries(rooms.map((r, i) => [r.name, out[i]]));
}
EOF
