const SHORT_HAUL_KM = 500;
const SHORT_HAUL_EXTRA_KG = 50; // take-off and landing

// Whole kilograms of CO2 for a flight of `km` in the given cabin.
export function flightKg(km, cabin) {
  if (!Object.hasOwn(KG_PER_KM, cabin)) {
    throw new RangeError(`Unknown cabin: ${cabin}`);
  }
  const extra = km < SHORT_HAUL_KM ? SHORT_HAUL_EXTRA_KG : 0;
  return Math.round(km * KG_PER_KM[cabin] + extra);
}
