import { test } from "node:test";
import assert from "node:assert/strict";
import { flightKg } from "../src/flights.js";

test("economy is 0.15 kg per km", () => {
  assert.equal(flightKg(1000, "economy"), 150);
});

test("business is 2.9 times economy", () => {
  assert.equal(flightKg(1000, "business"), 435);
});

test("flights under 500 km add 50 kg", () => {
  assert.equal(flightKg(100, "economy"), 65);
  assert.equal(flightKg(500, "economy"), 75);
});

test("unknown cabin throws RangeError", () => {
  assert.throws(() => flightKg(100, "first"), RangeError);
});
